import {
  CallHandler,
  CanActivate,
  Controller,
  ExecutionContext,
  Get,
  INestApplication,
  Injectable,
  Module,
  NestInterceptor,
  Observable,
  PipeTransform,
  Query,
} from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';
import * as net from 'net';
import { AppModule } from '../src/app.module.js';
import { appCounters, resetAppCounters } from '../src/app.controller.js';

interface RawResponse {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}

const request = (
  port: number,
  path: string,
  agent?: http.Agent,
): Promise<RawResponse> =>
  new Promise<RawResponse>((resolve, reject) => {
    http
      .get(
        `http://localhost:${port}${path}`,
        agent
          ? { agent }
          : {
              // Explicitly close connection after response to speed up server shutdown
              headers: { Connection: 'close' },
            },
        res => {
          let body = '';
          res.on('data', chunk => (body += chunk));
          res.on('end', () =>
            resolve({
              status: res.statusCode || 0,
              headers: res.headers,
              body,
            }),
          );
        },
      )
      .on('error', reject);
  });

const post = (
  port: number,
  path: string,
  body: string,
  agent?: http.Agent,
): Promise<RawResponse> =>
  new Promise<RawResponse>((resolve, reject) => {
    const req = http.request(
      `http://localhost:${port}${path}`,
      {
        method: 'POST',
        agent,
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(body),
          ...(agent ? {} : { Connection: 'close' }),
        },
      },
      res => {
        let data = '';
        res.on('data', chunk => (data += chunk));
        res.on('end', () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            body: data,
          }),
        );
      },
    );
    req.on('error', reject);
    req.end(body);
  });

const counters = {
  guard: 0,
  pipe: 0,
  interceptor: 0,
  handler: 0,
};

@Injectable()
class CountingGuard implements CanActivate {
  canActivate() {
    counters.guard++;
    return true;
  }
}

@Injectable()
class CountingPipe implements PipeTransform {
  transform(value: unknown) {
    counters.pipe++;
    return value;
  }
}

@Injectable()
class CountingInterceptor implements NestInterceptor {
  intercept(_context: ExecutionContext, next: CallHandler): Observable<any> {
    counters.interceptor++;
    return next.handle();
  }
}

@Controller()
class SideEffectController {
  @Get('slow')
  async slow(@Query('q', CountingPipe) _q?: string) {
    counters.handler++;
    // Simulate work
    await new Promise(resolve => setTimeout(resolve, 500));
    return 'ok';
  }

  @Get('boom')
  async boom() {
    await new Promise(resolve => setTimeout(resolve, 100));
    throw new Error('boom');
  }
}

@Module({
  controllers: [SideEffectController],
})
class SideEffectModule {}

