import { NestFactory } from '@nestjs/core';
import { ExpressAdapter } from '@nestjs/platform-express';
import { INestApplication } from '@nestjs/common';
import * as http from 'http';
import { AppModule } from '../src/app.module.js';

describe('Graceful Shutdown (Express)', () => {
  let app: INestApplication;

  afterEach(async () => {
    if (app) {
      await app.close();
    }
  });

  it('should allow in-flight requests to complete when return503OnClosing is enabled', async () => {
    app = await NestFactory.create(AppModule, new ExpressAdapter() as any, {
      return503OnClosing: true,
      logger: false,
    });
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    const requestPromise = new Promise<string>((resolve, reject) => {
      http
        .get(
          `http://localhost:${port}/slow`,
          {
            // Explicitly close connection after response to speed up server shutdown
            headers: { Connection: 'close' },
          },
          res => {
            let data = '';
            res.on('data', c => (data += c));
            res.on('end', () => resolve(data));
          },
        )
        .on('error', reject);
    });

    // Wait to ensure request is processing
    await new Promise(r => setTimeout(r, 100));

    const closePromise = app.close();

    // The in-flight request should finish successfully
    const response = await requestPromise;
    expect(response).toBe('ok');

    await closePromise;
  }, 10000);

  it('should return 503 for NEW queued requests on existing connections during shutdown', async () => {
    app = await NestFactory.create(AppModule, new ExpressAdapter() as any, {
      return503OnClosing: true,
      logger: false,
    });
    await app.listen(0);
    const port = app.getHttpServer().address().port;

    // Force 1 socket to ensure queuing/reuse
    const agent = new http.Agent({ keepAlive: true, maxSockets: 1 });

    // 1. Send Request A (slow) - occupies the socket
    const req1 = http.get(`http://localhost:${port}/slow`, { agent });

    // 2. Wait so Request A is definitely "in flight"
    await new Promise(r => setTimeout(r, 100));

    // 3. Trigger Shutdown (don't await yet)
    const closePromise = app.close();

    // Allow the microtask for prepareClose() to flush (sets isShuttingDown)
    await new Promise(r => setTimeout(r, 0));

    // 4. Send Request B immediately using the same agent.
    const statusPromise = new Promise<number>((resolve, reject) => {
      const req = http.get(`http://localhost:${port}/slow`, { agent }, res => {
        resolve(res.statusCode || 0);
      });
      req.on('error', reject);
    });

    // 5. Cleanup Request A
    req1.on('error', () => {});

    const status = await statusPromise;
    expect(status).toBe(503);

    await closePromise;
    agent.destroy();
  }, 10000);
});
import { Body, Controller, Get, Post, Query } from '@nestjs/common';

/**
 * Mutable counters so that e2e tests can observe how far requests travelled
 * into the Nest pipeline and how many times shutdown cleanup ran.
 */
export const appCounters = {
  /** Requests that reached a route handler. */
  handlerEntries: 0,
  /** "/echo" invocations, incremented only once the full body was received. */
  echoCount: 0,
  /** Module cleanup ("onModuleDestroy") executions. */
  cleanupCount: 0,
};

export function resetAppCounters() {
  appCounters.handlerEntries = 0;
  appCounters.echoCount = 0;
  appCounters.cleanupCount = 0;
}

@Controller()
export class AppController {
  @Get('slow')
  async slow(@Query('delay') delay?: string) {
    appCounters.handlerEntries++;
    // Simulate work; the delay is configurable via the "delay" query param
    const ms = delay === undefined ? 500 : Number(delay);
    await new Promise(resolve => setTimeout(resolve, ms));
    return 'ok';
  }

  @Get('error')
  async error() {
    appCounters.handlerEntries++;
    // Simulate work before failing, so tests can shut down mid-flight
    await new Promise(resolve => setTimeout(resolve, 100));
    throw new Error('boom');
  }

  @Post('echo')
  echo(@Body() body: unknown) {
    // Only reached once the request body has been fully received and parsed
    appCounters.handlerEntries++;
    appCounters.echoCount++;
    return body;
  }

  /**
   * Single endpoint bundling the probe behaviors the shutdown gate can be
   * observed through, independent of the route shape:
   * - GET  ?mode=slow   resolves with "ok" after "delay" ms (default 500)
   * - GET  ?mode=error  throws a business error after "delay" ms
   * - GET  ?mode=stats  reports the shared counters without disturbing them
   * - POST ?mode=echo   increments the counters only once the full body was
   *                     received and echoes the parsed body back
   */
  @Get('graceful-probe')
  async gracefulProbe(
    @Query('mode') mode?: string,
    @Query('delay') delay?: string,
  ) {
    if (mode === 'stats') {
      return { ...appCounters };
    }
    appCounters.handlerEntries++;
    const ms = delay === undefined ? 500 : Number(delay);
    await new Promise(resolve => setTimeout(resolve, ms));
    if (mode === 'error') {
      throw new Error('boom');
    }
    return 'ok';
  }

  @Post('graceful-probe')
  gracefulProbeEcho(@Query('mode') mode: string, @Body() body: unknown) {
    // Only reached once the request body has been fully received and parsed
    appCounters.handlerEntries++;
    if (mode === 'echo') {
      appCounters.echoCount++;
    }
    return body;
  }
}
import { Module, OnModuleDestroy } from '@nestjs/common';
import { AppController, appCounters } from './app.controller.js';

@Module({
  controllers: [AppController],
})
export class AppModule implements OnModuleDestroy {
  onModuleDestroy() {
    appCounters.cleanupCount++;
  }
}
