731	  public async createMiddlewareFactory(
732	    requestMethod: RequestMethod,
733	  ): Promise<(path: string, callback: Function) => any> {
734	    if (!this.isMiddieRegistered) {
735	      await this.registerMiddie();
736	    }
737	    return (path: string, callback: Function) => {
738	      const hasEndOfStringCharacter = path.endsWith('$');
739	      path = hasEndOfStringCharacter ? path.slice(0, -1) : path;
740	
741	      let normalizedPath = LegacyRouteConverter.tryConvert(path);
742	
743	      // Fallback to "*path" to support plugins like GraphQL
744	      normalizedPath = normalizedPath === '/*path' ? '*path' : normalizedPath;
745	
746	      // Normalize the path to support the prefix if it set in application
747	      if (
748	        this._pathPrefix &&
749	        !normalizedPath.startsWith(this._pathPrefix) &&
750	        (normalizedPath === '/' || normalizedPath === '')
751	      ) {
752	        normalizedPath = `${this._pathPrefix}${normalizedPath}`;
753	        if (normalizedPath.endsWith('/')) {
754	          normalizedPath = `${normalizedPath}{*path}`;
755	        }
756	      }
757	
758	      try {
759	        let { regexp: re } = pathToRegexp(normalizedPath);
760	        re = hasEndOfStringCharacter
761	          ? new RegExp(re.source + '$', re.flags)
762	          : re;
763	
764	        // The following type assertion is valid as we use import('@fastify/middie') rather than require('@fastify/middie')
765	        // ref https://github.com/fastify/middie/pull/55
766	        this.instance.use(
767	          normalizedPath,
768	          (req: any, res: any, next: Function) => {
769	            const queryParamsIndex = req.originalUrl.indexOf('?');
770	            let pathname =
771	              queryParamsIndex >= 0
772	                ? req.originalUrl.slice(0, queryParamsIndex)
773	                : req.originalUrl;
774	
775	            pathname = this.sanitizeUrl(pathname);
776	
777	            if (normalizedPath) {
778	              const pathToCheck = pathname.endsWith('/')
779	                ? pathname
780	                : `${pathname}/`;
781	              if (!re.exec(pathToCheck)) {
782	                return next();
783	              }
784	            }
785	            return callback(req, res, next);
786	          },
787	        );
788	      } catch (e) {
789	        if (e instanceof TypeError) {
790	          LegacyRouteConverter.printError(path);
791	        }
792	        throw e;
793	      }
794	    };
795	  }
