/**
 * Installs a request gate in front of Fastify's routing so that, once the
 * shutdown has started, new requests are rejected with
 * "503 Service Unavailable" before they can enter the Nest pipeline
 * (middleware, guards, pipes, interceptors, handlers), while requests
 * that were already accepted run to completion.
 *
 * The gate has three layers:
 *
 * - a wrapper around the server's "request" listener, which rejects every
 *   request whose headers arrive after the shutdown started — including
 *   requests pipelined on an existing keep-alive connection. The listener
 *   is wrapped instead of using a Fastify "onRequest" hook because
 *   Fastify's own "return503OnClosing" fast path (enabled by default)
 *   runs before any hook and answers with a JSON body, which would not
 *   match the Express-compatible contract (a plain "Service Unavailable"
 *   body and a "Connection: close" header);
 * - a "preHandler" hook, which covers requests that were accepted by the
 *   first layer while the application was still running but have not
 *   reached a route handler yet when the shutdown starts — most notably
 *   requests whose body is still streaming in. Fastify runs "preHandler"
 *   hooks after the request body has been fully received and right before
 *   the route handler (where the Nest pipeline begins), so a late
 *   rejection here still happens before any guard, pipe, interceptor or
 *   controller runs and cannot trigger business side effects;
 * - a wrapper around the server's "upgrade" event emission, which rejects
 *   upgrades whose handshake arrives after the shutdown started — including
 *   upgrades attempted on a reused keep-alive connection — with the very
 *   same 503 response, while sockets of upgrades accepted earlier are
 *   tracked and drained by "beforeClose()" so established WebSocket
 *   connections can finish their in-flight work.
 */
private installClosingRequestGate() {
  const server = this.httpServer as unknown as http.Server;
  const routing = this.instance.routing;
  server.removeListener('request', routing);
  server.on('request', (req, res) => {
    if (!this.isShuttingDown) {
      routing(req as unknown as TRawRequest, res as unknown as TRawResponse);
      return;
    }
    if (req.httpVersionMajor !== 2) {
      res.setHeader('Connection', 'close');
    }
    res.writeHead(HttpStatus.SERVICE_UNAVAILABLE, {
      'Content-Type': 'text/plain',
    });
    res.end('Service Unavailable');
  });

  this.instance.addHook('preHandler', (request, reply, done) => {
    if (!this.isShuttingDown) {
      done();
      return;
    }
    if (request.raw.httpVersionMajor !== 2) {
      reply.header('Connection', 'close');
    }
    // Short-circuit the lifecycle without calling "done()".
    reply
      .code(HttpStatus.SERVICE_UNAVAILABLE)
      .header('Content-Type', 'text/plain')
      .send('Service Unavailable');
  });

  this.installClosingUpgradeGate(server);
}

/**
 * Intercepts the server's "upgrade" event at its source (the emitter) so
 * that:
 *
 * - every upgrade observed after the shutdown state was established is
 *   answered with "503 Service Unavailable", a "Connection: close" header
 *   and a plain-text body, and the underlying socket is destroyed. The
 *   event never reaches the registered WebSocket servers or any business
 *   gateway/message handler;
 * - upgrades observed before the shutdown started run through the registered
 *   listeners unchanged, but their sockets are tracked until they close,
 *   allowing "beforeClose()" to wait for established connections to drain.
 *
 * Intercepting "emit" rather than wrapping "addListener"/"on" keeps the
 * interception effective no matter how the upgrade listener was attached
 * (the "@nestjs/platform-ws" adapter uses "server.on()", but user code and
 * third-party libraries may register listeners directly) and guarantees the
 * rejection happens strictly before any listener runs.
 */
private installClosingUpgradeGate(server: http.Server) {
  const originalEmit = server.emit.bind(server) as (
    event: string,
    ...args: any[]
  ) => boolean;
  server.emit = (event: string, ...args: any[]) => {
    if (event !== 'upgrade') {
      return originalEmit(event, ...args);
    }
    const [request, socket] = args as [http.IncomingMessage, Duplex];
    if (this.isShuttingDown) {
      return this.rejectUpgrade(request, socket);
    }
    this.trackUpgradeSocket(socket);
    return originalEmit(event, ...args);
  };
}

private rejectUpgrade(request: http.IncomingMessage, socket: Duplex) {
  // Mirrors the request gate's rejection contract. The reason phrase is
  // emitted explicitly because "http.ServerResponse" is not involved here:
  // the upgrade hands us the raw net socket.
  const body = 'Service Unavailable';
  if (!socket.destroyed && !socket.writableEnded) {
    socket.write(
      `HTTP/${request.httpVersion ?? '1.1'} 503 Service Unavailable\r\n` +
        'Content-Type: text/plain\r\n' +
        'Connection: close\r\n' +
        `Content-Length: ${Buffer.byteLength(body)}\r\n` +
        '\r\n' +
        body,
    );
    socket.end();
    socket.destroySoon?.();
    socket.destroy();
  }
  // Node treats a truthy return from "emit" as "there was a listener".
  return true;
}

private trackUpgradeSocket(socket: Duplex) {
  this.trackedUpgradeSockets.add(socket);
  const untrack = () => {
    if (!this.trackedUpgradeSockets.delete(socket)) {
      return;
    }
    if (this.trackedUpgradeSockets.size === 0) {
      const resolvers = this.upgradesDrainedResolvers.splice(0);
      resolvers.forEach(resolve => resolve());
    }
  };
  socket.once('close', untrack);
  // Defensive: a misbehaving upgrade listener that leaves the socket open
  // without attaching a 'close' handler would otherwise pin the shutdown
  // forever. 'error' always precedes 'close', which performs the untrack.
  socket.once('error', () => socket.destroy());
}

