      // the socket so an unhandled upgrade cannot linger on the connection.
      if ((this.httpServer?.listenerCount('upgrade') ?? 0) === 1) {
        socket.destroy();
      }
      return;
    }
    this.wss!.handleUpgrade(request, socket, head, ws => {
      this.wss!.emit('connection', ws, request);
    });
  }

