import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import WebSocket from 'ws';
import { AppModule } from '../src/app.module.js';
import { wsCounters } from '../src/graceful-ws.gateway.js';

describe('debug drain', () => {
  it('logs convergence', async () => {
    const app = await NestFactory.create<NestFastifyApplication>(
      AppModule,
      new FastifyAdapter({ return503OnClosing: true }),
      { logger: false },
    );
    await app.listen(0);
    const port = app.getHttpServer().address().port;
    const mk = () => {
      const ws = new WebSocket(`ws://localhost:${port}/graceful-ws`);
      return new Promise<WebSocket>((res, rej) => {
        ws.once('open', () => res(ws));
        ws.once('error', rej);
      });
    };
    const erroring = await mk();
    const aborting = await mk();
    const delayed = await mk();
    console.log('open', JSON.stringify(wsCounters));

    delayed.send(JSON.stringify({ type: 'echo', data: 'last', delay: 300 }));
    erroring.send(JSON.stringify({ type: 'error' }));

    const t0 = Date.now();
    const p = app
      .close()
      .then(() => console.log('app.close resolved at', Date.now() - t0, JSON.stringify(wsCounters)));
    setTimeout(() => {
      console.log('terminate @30', JSON.stringify(wsCounters));
      aborting.terminate();
    }, 30);
    erroring.once('close', c =>
      console.log('erroring closed', c, Date.now() - t0),
    );
    delayed.once('message', d =>
      console.log('delayed msg', d.toString(), Date.now() - t0),
    );
    delayed.once('close', c =>
      console.log('delayed closed', c, Date.now() - t0),
    );
    const r = await Promise.race([
      p,
      new Promise(res => setTimeout(() => res('TIMEOUT'), 3000)),
    ]);
    console.log('race:', r);
    await app.close();
  }, 20000);
});

