941	   * Intercepts the server's "upgrade" event at its source (the emitter) so
942	   * that every upgrade observed after the shutdown state was established is
943	   * answered with "503 Service Unavailable", a "Connection: close" header and
944	   * a plain-text body, after which the socket is closed. The event never
945	   * reaches the registered WebSocket servers or any business gateway/message
946	   * handler, and the rejected socket is not tracked as a connection.
947	   *
948	   * Upgrades observed before the shutdown started pass through unchanged.
949	   * Their sockets stay owned by the registered WebSocket machinery, and
950	   * Node's own "server.close()" (invoked by "fastify.close()") already keeps
951	   * the server alive until those connections end, which lets established
952	   * connections finish their in-flight work during shutdown.
953	   *
954	   * Intercepting "emit" rather than wrapping "addListener"/"on" keeps the
955	   * rejection effective no matter how the upgrade listener was attached (the
956	   * "@nestjs/platform-ws" adapter uses "server.on()", but user code and
957	   * third-party libraries may register listeners directly) and guarantees it
958	   * runs strictly before any listener.
959	   */
960	  private installClosingUpgradeGate(server: http.Server) {
961	    const originalEmit = server.emit.bind(server) as (
962	      event: string,
963	      ...args: any[]
964	    ) => boolean;
965	    server.emit = (event: string, ...args: any[]) => {
966	      if (event !== 'upgrade' || !this.isShuttingDown) {
967	        return originalEmit(event, ...args);
968	      }
969	      const [request, socket] = args as [http.IncomingMessage, Duplex];
970	      return this.rejectUpgrade(request, socket);
971	    };
972	  }
