974	  private rejectUpgrade(request: http.IncomingMessage, socket: Duplex) {
975	    // Mirrors the request gate's rejection contract. The reason phrase is
976	    // emitted explicitly because "http.ServerResponse" is not involved here:
977	    // the upgrade hands us the raw net socket.
978	    const body = 'Service Unavailable';
979	    // Node detaches an upgraded socket from the server's own error handling,
980	    // so a client RST right after the rejection would otherwise surface as an
981	    // unhandled 'error' and crash the process.
982	    socket.on('error', () => {});
983	    if (!socket.destroyed && !socket.writableEnded) {
984	      socket.write(
985	        `HTTP/${request.httpVersion ?? '1.1'} 503 Service Unavailable\r\n` +
986	          'Content-Type: text/plain\r\n' +
987	          'Connection: close\r\n' +
988	          `Content-Length: ${Buffer.byteLength(body)}\r\n` +
989	          '\r\n' +
